insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000492011', '40000000-0000-4000-8000-000000049201', 'Comece identificando qual relação vetorial ou geométrica está sendo pedida; essa escolha vem antes da substituição numérica.', 1), ('60000000-0000-4000-8000-000000492012', '40000000-0000-4000-8000-000000049201', 'A área do paralelogramo é o módulo do produto vetorial.', 2), ('60000000-0000-4000-8000-000000492013', '40000000-0000-4000-8000-000000049201', 'Os vetores são perpendiculares, então a área também é o produto dos módulos.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049201', '$A=4$.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. O produto vetorial produz um vetor perpendicular aos dois fatores, com sentido determinado pela regra da mão direita. Seu módulo também mede a área do paralelogramo; o produto misto acrescenta um terceiro vetor e mede volume orientado. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000492011', '40000000-0000-4000-8000-000000049201', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000492012', '40000000-0000-4000-8000-000000049201', 'Calcule o produto', '$u \times v=(0,0,4).$', 2), ('70000000-0000-4000-8000-000000492013', '40000000-0000-4000-8000-000000049201', 'Tome o módulo', '$|u \times v|=4.$', 3), ('70000000-0000-4000-8000-000000492014', '40000000-0000-4000-8000-000000049201', 'Interprete', 'Esse módulo é a área do paralelogramo.', 4), ('70000000-0000-4000-8000-000000492015', '40000000-0000-4000-8000-000000049201', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
